begin;
create table public.payment_providers(id uuid primary key default gen_random_uuid(),key text not null unique,name text not null,enabled boolean not null default false,priority integer not null default 100,health_status text not null default 'misconfigured' check(health_status in('healthy','degraded','unavailable','disabled','misconfigured')),sandbox_supported boolean not null default false,production_verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.provider_capabilities(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.payment_providers(id) on delete cascade,capability text not null,environment text not null check(environment in('sandbox','production')),enabled boolean not null default false,documentation_url text,verified_at timestamptz,created_at timestamptz not null default now(),unique(provider_id,capability,environment));
create table public.organisation_providers(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,provider_id uuid not null references public.payment_providers(id),environment text not null check(environment in('sandbox','production')),status text not null default 'pending' check(status in('pending','sandbox','live','disabled','suspended')),priority integer not null default 100,is_default boolean not null default false,is_fallback boolean not null default false,enabled_methods text[] not null default '{}',credential_status text not null default 'missing',webhook_status text not null default 'unconfigured',last_health_check_at timestamptz,live_approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organisation_id,provider_id,environment));
create table public.provider_credentials(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,provider_id uuid not null references public.payment_providers(id),environment text not null check(environment in('sandbox','production')),name text not null,public_identifier text,secret_reference text not null,version integer not null default 1,status text not null default 'active' check(status in('active','rotated','revoked')),created_by uuid references public.profiles(id),created_at timestamptz not null default now(),rotated_at timestamptz,revoked_at timestamptz,unique(organisation_id,provider_id,environment,name,version));
create table public.provider_health_checks(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.payment_providers(id),organisation_id uuid references public.organisations(id),environment text not null check(environment in('sandbox','production')),status text not null,latency_ms integer,authentication_error boolean not null default false,configuration_error boolean not null default false,failure_rate numeric(5,2),safe_message text,checked_at timestamptz not null default now());
create table public.provider_routing_rules(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,payment_method text,mandate_method text,environment text not null check(environment in('sandbox','production')),provider_id uuid not null references public.payment_providers(id),backup_provider_id uuid references public.payment_providers(id),min_amount numeric(14,2),max_amount numeric(14,2),priority integer not null default 100,manual_override boolean not null default false,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.provider_requests(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),provider_id uuid not null references public.payment_providers(id),environment text not null,operation text not null,idempotency_key text not null,request_hash text not null,safe_metadata jsonb not null default '{}',status text not null default 'pending',created_at timestamptz not null default now(),completed_at timestamptz,unique(organisation_id,idempotency_key));
create table public.provider_responses(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.provider_requests(id) on delete cascade,provider_reference text,status text not null,safe_metadata jsonb not null default '{}',received_at timestamptz not null default now());
create table public.provider_errors(id uuid primary key default gen_random_uuid(),organisation_id uuid references public.organisations(id),provider_id uuid not null references public.payment_providers(id),request_id uuid references public.provider_requests(id),category text not null,code text not null,safe_message text not null,retryable boolean not null default false,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.provider_webhook_events(id uuid primary key default gen_random_uuid(),organisation_id uuid references public.organisations(id),provider text not null,event_id text not null,environment text not null default 'sandbox',signature_verified boolean not null default false,processing_status text not null,safe_metadata jsonb not null default '{}',received_at timestamptz not null default now(),processed_at timestamptz,unique(provider,event_id,environment));
create table public.idempotency_records(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),operation_type text not null,provider text not null,idempotency_key text not null,request_hash text not null,response_reference text,status text not null,expires_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organisation_id,operation_type,idempotency_key));
create table public.mandate_attempts(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),mandate_id uuid not null references public.mandates(id),provider_id uuid not null references public.payment_providers(id),environment text not null,attempt_number integer not null,provider_reference text,routing_reason jsonb not null default '[]',status text not null,safe_failure_message text,created_at timestamptz not null default now());
create table public.payment_attempts(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),payment_id uuid not null references public.payments(id),provider_id uuid not null references public.payment_providers(id),environment text not null,attempt_number integer not null,provider_reference text,routing_reason jsonb not null default '[]',status text not null,failure_category text,safe_failure_message text,created_at timestamptz not null default now());
create table public.settlement_imports(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),provider_id uuid not null references public.payment_providers(id),environment text not null,source text not null check(source in('api','csv_placeholder')),file_path text,status text not null,record_count integer not null default 0,imported_by uuid references public.profiles(id),created_at timestamptz not null default now(),completed_at timestamptz);
create table public.reconciliation_records(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),provider_id uuid not null references public.payment_providers(id),payment_id uuid references public.payments(id),settlement_id uuid references public.settlements(id),issue_type text not null check(issue_type in('missing_record','amount_mismatch','status_mismatch','duplicate_reference','settlement_mismatch')),internal_value jsonb not null default '{}',provider_value jsonb not null default '{}',status text not null default 'open' check(status in('open','reviewing','resolved','accepted')),resolution_notes text,resolved_by uuid references public.profiles(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.merchant_onboarding_cases(id uuid primary key default gen_random_uuid(),organisation_id uuid not null unique references public.organisations(id),status text not null default 'organisation_created',business_profile jsonb not null default '{}',required_payment_methods text[] not null default '{}',estimated_monthly_volume numeric(14,2),average_transaction_value numeric(14,2),internal_reviewer_id uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.merchant_documents(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),case_id uuid not null references public.merchant_onboarding_cases(id),document_type text not null,storage_path text not null unique,mime_type text not null,size_bytes bigint not null,review_status text not null default 'pending' check(review_status in('pending','approved','rejected','expired')),rejection_reason text,expires_at date,malware_scan_status text not null default 'pending_placeholder',uploaded_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.merchant_provider_applications(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),case_id uuid not null references public.merchant_onboarding_cases(id),provider_id uuid not null references public.payment_providers(id),status text not null default 'created',sandbox_approved_at timestamptz,live_approved_at timestamptz,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(case_id,provider_id));
create table public.merchant_approval_history(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),case_id uuid not null references public.merchant_onboarding_cases(id),from_status text,to_status text not null,safe_notes text,actor_id uuid references public.profiles(id),created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['organisation_providers','provider_credentials','provider_health_checks','provider_routing_rules','provider_requests','provider_responses','provider_errors','provider_webhook_events','idempotency_records','mandate_attempts','payment_attempts','settlement_imports','reconciliation_records','merchant_onboarding_cases','merchant_documents','merchant_provider_applications','merchant_approval_history'] loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);end loop;end$$;
do $$ declare t text; begin foreach t in array array['organisation_providers','provider_credentials','provider_health_checks','provider_routing_rules','provider_requests','provider_errors','provider_webhook_events','idempotency_records','mandate_attempts','payment_attempts','settlement_imports','reconciliation_records','merchant_onboarding_cases','merchant_documents','merchant_provider_applications','merchant_approval_history'] loop execute format('create policy %I on public.%I for select to authenticated using(public.is_super_admin() or (organisation_id is not null and public.is_organisation_member(organisation_id)))',t||'_tenant_read',t);execute format('create policy %I on public.%I for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin())',t||'_admin_write',t);end loop;end$$;
alter table public.payment_providers enable row level security;alter table public.payment_providers force row level security;create policy payment_providers_admin on public.payment_providers for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());create policy payment_providers_read on public.payment_providers for select to authenticated using(true);
alter table public.provider_capabilities enable row level security;alter table public.provider_capabilities force row level security;create policy provider_capabilities_admin on public.provider_capabilities for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());create policy provider_capabilities_read on public.provider_capabilities for select to authenticated using(true);
create index organisation_providers_org_idx on public.organisation_providers(organisation_id,environment,status) where deleted_at is null;create index provider_requests_org_idx on public.provider_requests(organisation_id,created_at desc);create index provider_webhook_events_status_idx on public.provider_webhook_events(processing_status,received_at);create index idempotency_expiry_idx on public.idempotency_records(expires_at);create index onboarding_status_idx on public.merchant_onboarding_cases(status,updated_at desc) where deleted_at is null;create index reconciliation_open_idx on public.reconciliation_records(organisation_id,status,created_at desc);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('merchant-kyc','merchant-kyc',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy merchant_kyc_select on storage.objects for select to authenticated using(bucket_id='merchant-kyc' and public.is_organisation_member((storage.foldername(name))[1]::uuid));create policy merchant_kyc_insert on storage.objects for insert to authenticated with check(bucket_id='merchant-kyc' and public.is_organisation_member((storage.foldername(name))[1]::uuid));
insert into public.payment_providers(key,name,sandbox_supported) values('razorpay','Razorpay',true),('phonepe','PhonePe Payment Gateway',true),('cashfree','Cashfree',true),('jio-pg','Jio Payment Gateway',false),('sabpaisa','SabPaisa',false),('mock','FirstPay Mock Provider',true) on conflict(key) do nothing;
commit;
